FUNCTION_BLOCK FB_S13
VAR_INPUT
    LineRun : BOOL;
    PartAtMerge : BOOL;
    PartOnMain : BOOL;
    JamSensor : BOOL;
    ResetBtn : BOOL;
    ModeAuto : BOOL;
END_VAR
VAR_OUTPUT
    MainMotor : BOOL := FALSE;
    MergeMotor : BOOL := FALSE;
    SpeedHigh : BOOL := FALSE;
    JamAlarm : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    LineRunLast : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    LineRunRise : BOOL := FALSE;
    ResetBtnRise : BOOL := FALSE;
    ResetAccepted : BOOL := FALSE;
    JamCount : UINT := UINT#0;
    PartTrueCount : UINT := UINT#0;
    PartFalseCount : UINT := UINT#0;
END_VAR

(*
    每次调用代表一个20 ms扫描；计数在第100、150、250个
    连续满足条件的扫描达到阈值，计数器饱和，避免溢出。

    待审语义冲突（输入告警列表虽为空，以下差异仍存在）：
    1. C5由单次JamSensor且LineRun触发未来报警义务，
       不要求连续100周期；需求原文要求连续堵料才报警。
    2. C7由单次有料触发未来升档义务，不要求连续有料，
       也没有后续停机的取消条件；原文要求运行且连续150周期。
    3. C10要求初始区间输出全停，与首次调用LineRun为TRUE时
       按LineRunLast=FALSE识别上升沿并立即启动存在冲突。
    4. LineRun=FALSE时Status必须为0000，与报警锁存期间
       Status保持8C01的解读存在冲突。
    5. C6使用当前复位电平约束下一周期报警；原文采用当前
       ResetBtn上升沿清报警，两者的边沿和跨周期语义不等价。
    6. 手动点动没有对应输入接口；本块在手动模式不生成
       自动启动、送料恢复或换档，只保留输出并施加安全联锁。

    实现采用需求原文的连续计数、当前扫描边沿及总停优先语义；
    不额外插入上电屏蔽周期，不声称同时满足上述冲突规约。
    未经真实编译器与逐周期测试验证。
*)

(* 所有模式下采集边沿；模式切换本身不构成启动边沿。 *)
LineRunRise := LineRun AND NOT LineRunLast;
ResetBtnRise := ResetBtn AND NOT ResetBtnLast;
ResetAccepted := ResetBtnRise AND NOT JamSensor;

(* 堵料监测不因停线或手动模式而停止。 *)
IF JamSensor THEN
    IF JamCount < UINT#100 THEN
        JamCount := JamCount + UINT#1;
    END_IF;
ELSE
    JamCount := UINT#0;
END_IF;

IF JamCount >= UINT#100 THEN
    JamAlarm := TRUE;
END_IF;

(* 有效复位优先于启动；同一扫描的启动边沿不会被采用。 *)
IF ResetAccepted THEN
    JamAlarm := FALSE;
    Status := WORD#16#0000;
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    PartTrueCount := UINT#0;
    PartFalseCount := UINT#0;
END_IF;

(* 总停、报警、复位均高于自动运行。 *)
IF NOT LineRun THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    Status := WORD#16#0000;
    PartTrueCount := UINT#0;
    PartFalseCount := UINT#0;

ELSIF JamAlarm THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    Status := WORD#16#8C01;
    PartTrueCount := UINT#0;
    PartFalseCount := UINT#0;

ELSIF ResetAccepted THEN
    (* 输出已清零；必须在以后扫描出现新的LineRun上升沿。 *)
    Status := WORD#16#0000;

ELSIF ModeAuto THEN
    Status := WORD#16#0000;

    IF LineRunRise THEN
        MainMotor := TRUE;
    END_IF;

    MergeMotor := MainMotor AND NOT PartAtMerge;

    IF PartOnMain THEN
        PartFalseCount := UINT#0;

        IF MainMotor THEN
            IF PartTrueCount < UINT#150 THEN
                PartTrueCount := PartTrueCount + UINT#1;
            END_IF;

            IF PartTrueCount >= UINT#150 THEN
                SpeedHigh := TRUE;
            END_IF;
        ELSE
            PartTrueCount := UINT#0;
        END_IF;
    ELSE
        PartTrueCount := UINT#0;

        IF PartFalseCount < UINT#250 THEN
            PartFalseCount := PartFalseCount + UINT#1;
        END_IF;

        IF PartFalseCount >= UINT#250 THEN
            SpeedHigh := FALSE;
        END_IF;
    END_IF;

ELSE
    (* 手动模式不自动改变运行或档位；连续换档计数重新开始。 *)
    Status := WORD#16#0000;
    PartTrueCount := UINT#0;
    PartFalseCount := UINT#0;
END_IF;

(* 最终防撞与主从联锁：任何模式均不得旁路。 *)
IF PartAtMerge OR NOT MainMotor THEN
    MergeMotor := FALSE;
END_IF;

LineRunLast := LineRun;
ResetBtnLast := ResetBtn;

END_FUNCTION_BLOCK
